import{_ as e,c as t,o as s,a4 as n}from"./chunks/framework.ttppV29E.js";const a="/assets/File-settings.BZ84muqX.png",i="/assets/Test-set-settings.D5G_ui8k.png",T=JSON.parse('{"title":"File and Test Set Settings","description":"","frontmatter":{},"headers":[],"relativePath":"docs/using-the-test-editor/file-and-test-set-settings.md","filePath":"docs/using-the-test-editor/file-and-test-set-settings.md","lastUpdated":1792486760000}'),o={name:"docs/using-the-test-editor/file-and-test-set-settings.md"},r=n('<h1 id="file-and-test-set-settings" tabindex="-1">File and Test Set Settings <a class="header-anchor" href="#file-and-test-set-settings" aria-label="Permalink to &quot;File and Test Set Settings&quot;">​</a></h1><h2 id="updating-file-test-set-settings" tabindex="-1">Updating File/Test Set Settings <a class="header-anchor" href="#updating-file-test-set-settings" aria-label="Permalink to &quot;Updating File/Test Set Settings&quot;">​</a></h2><p>Selecting an item in the Repositories Tree View displays its details in the File / Test Set Settings panel on the right side of the screen, where you can update its settings.</p><h3 id="file-settings" tabindex="-1">File Settings <a class="header-anchor" href="#file-settings" aria-label="Permalink to &quot;File Settings&quot;">​</a></h3><p>When you select a file or folder in the tree view, you can rename it. Feature files must use the <code>.feature</code> extension, and step definition files must use the <code>.step</code> extension.</p><p><img src="'+a+'" alt="File Settings"></p><h3 id="test-set-settings" tabindex="-1">Test Set Settings <a class="header-anchor" href="#test-set-settings" aria-label="Permalink to &quot;Test Set Settings&quot;">​</a></h3><p><img src="'+i+'" alt="Test Set Settings"></p><h4 id="general-settings" tabindex="-1">General Settings <a class="header-anchor" href="#general-settings" aria-label="Permalink to &quot;General Settings&quot;">​</a></h4><ul><li><strong>Test set name</strong><br> A unique, descriptive name for this Test Set.</li><li><strong>Target Tenancy</strong><br> The organisation or tenant code the test set runs against (the <code>TargetOrg</code> key in <code>Configuration.json</code>).</li><li><strong>Target Instance</strong><br> The friendly name of the install-configured environment this Test Set runs against (e.g. <code>Prod</code>, <code>Stag</code>). This single choice determines which real AireForms/AireFrame/AireVault/AireGlu/AireFlow URLs your tests hit — you no longer type any of those URLs individually. A Test Set with no Target Instance selected, or one that names an instance your AireAssert install hasn&#39;t configured, will fail to start.</li></ul><h4 id="forms-tab" tabindex="-1">FORMS Tab <a class="header-anchor" href="#forms-tab" aria-label="Permalink to &quot;FORMS Tab&quot;">​</a></h4><table><thead><tr><th>Field</th><th>Config Key</th><th>Description</th></tr></thead><tbody><tr><td><strong>Callback Url</strong></td><td><code>CallbackUrl</code></td><td>Optional webhook endpoint to receive real-time test results.</td></tr></tbody></table><p>The AireForms server is resolved from the <strong>Target Instance</strong> selected in General Settings, and the organisation is set as <strong>Target Tenancy</strong> there too.</p><h4 id="aireglu-tab" tabindex="-1">AIREGLU Tab <a class="header-anchor" href="#aireglu-tab" aria-label="Permalink to &quot;AIREGLU Tab&quot;">​</a></h4><p>Configure your AireGlu integration — these settings map to the <code>AireGlu</code> section in your <code>Configuration.json</code>. You can provide:</p><ul><li><strong>Tenancy</strong></li></ul><p>The AireGlu Runtime and API URLs are resolved from the <strong>Target Instance</strong> selected in General Settings, not typed here.</p><h4 id="aireflow-tab" tabindex="-1">AIREFLOW Tab <a class="header-anchor" href="#aireflow-tab" aria-label="Permalink to &quot;AIREFLOW Tab&quot;">​</a></h4><p>Configure your AireFlow integration — these values populate the <code>AireFlow</code> section in your <code>Configuration.json</code>. You can specify:</p><ul><li><strong>Tenancy</strong></li></ul><p>The AireFlow Runtime URL is resolved from the <strong>Target Instance</strong> selected in General Settings, not typed here.</p><h4 id="aireframe-tab" tabindex="-1">AIREFRAME Tab <a class="header-anchor" href="#aireframe-tab" aria-label="Permalink to &quot;AIREFRAME Tab&quot;">​</a></h4><p>Configure the AireFrame users your tests log in as, and how long subject assertions are retried for. These values populate the <code>AireFrame</code> section of your <code>Configuration.json</code>, except for passwords and TOTP secrets, which are stored in AireVault rather than in your repository.</p><p>See <a href="./aireframe-settings.html">AireFrame Settings</a> for the full details, including reading a user&#39;s TOTP secret from a screenshot of AireFrame&#39;s 2FA setup QR code.</p><blockquote><p><strong>Note:</strong> After saving your changes, you can verify your integrations by using the <strong>Test Connection</strong> button on the <strong>AIREGLU</strong> and <strong>AIREFLOW</strong> tabs to ensure both connections are working correctly.</p></blockquote><p><strong>After updating any settings, click</strong> <strong>Save Changes</strong> <strong>at the bottom of the Test Editor panel</strong>. You will be prompted for a commit message.</p>',26),l=[r];function d(g,c,h,u,p,f){return s(),t("div",null,l)}const b=e(o,[["render",d]]);export{T as __pageData,b as default};
